112	// Check if spoken answer matches the correct answer (fuzzy matching)
113	function checkAnswer(spoken: string, correct: string): boolean {
114	  const normalizedSpoken = normalizeText(spoken);
115	  const normalizedCorrect = normalizeText(correct);
116	
117	  // Exact match
118	  if (normalizedSpoken === normalizedCorrect) return true;
119	
120	  // Check if spoken contains the answer
121	  if (normalizedSpoken.includes(normalizedCorrect)) return true;
122	  if (
123	    normalizedCorrect.includes(normalizedSpoken) &&
124	    normalizedSpoken.length > 3
125	  )
126	    return true;
127	
128	  // Check similarity (allow for small speech recognition errors)
129	  const spokenWords = normalizedSpoken.split(" ");
130	  const correctWords = normalizedCorrect.split(" ");
131	
132	  // Count matching words
133	  let matches = 0;
134	  for (const word of correctWords) {
135	    if (
136	      spokenWords.some(
137	        (sw) =>
138	          sw === word ||
139	          (sw.length > 3 &&
140	            word.length > 3 &&
141	            (sw.includes(word) ||
142	              word.includes(sw) ||
143	              levenshteinDistance(sw, word) <= Math.floor(word.length / 3))),
144	      )
145	    ) {
146	      matches++;
147	    }
148	  }
